  /**
   * PRRD (override) - post-recall release override date for offender.
   */
  postRecallReleaseOverrideDate?: string
  /**
   * DPRRD (override) - detention training order post-recall release override date for offender
   */
  dtoPostRecallReleaseDateOverride?: string
  /**
   * Release date for non-DTO sentence (if applicable). This will be based on one of ARD, CRD, NPD or PRRD.
   */
  nonDtoReleaseDate?: string
  /**
   * SED (calculated) - date on which sentence expires. (as calculated by NOMIS)
   */
  sentenceExpiryCalculatedDate?: string
  /**
   * SED (override) - date on which sentence expires.
   */
  sentenceExpiryOverrideDate?: string
  /**
   * LED (calculated) - date on which offender licence expires. (as calculated by NOMIS)
   */
  licenceExpiryCalculatedDate?: string
  /**
   * LED (override) - date on which offender licence expires.
   */
  licenceExpiryOverrideDate?: string
  /**
   * PED (calculated) - date on which offender is eligible for parole.
   */
  paroleEligibilityCalculatedDate?: string
  /**
   * PED (override) - date on which offender is eligible for parole.
   */
  paroleEligibilityOverrideDate?: string
  /**
   * TUSED (calculated) - top-up supervision expiry date for offender.
   */
